        if not state.get('receipt_checked', False):
            api.check_delivery_receipt()

        # Deliver if not already delivered
        if not state.get('delivered', False):
            api.deliver_once()

        # Acknowledge if delivered (and we have the lease, which we checked/need to ensure)
        # Note: release_lease requires acknowledged. So we acknowledge first.
        if state.get('delivered', False):
            api.acknowledge()

    # Step 3: Handle Transactional Flow (If profile is transactional)
    if state.get('transactional', False) and state.get('leased', False):
        # Ensure we are in a transaction before applying
        if not state.get('transaction', False):
            api.begin()
        # Now apply if not already applied
        if state.get('transaction', False) and not state.get('applied', False):
            api.apply_transactional()

